SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_phase3_mapping_scope_units e WHERE e.concept_id IS NOT NULL AND e.mapping_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM (SELECT * FROM mapping.phase3_concept_mappings UNION ALL SELECT * FROM expected_phase3_concept_mappings) p WHERE e.concept_id IS NOT DISTINCT FROM p.concept_id AND e.mapping_id IS NOT DISTINCT FROM p.mapping_id)) THEN 'FK_expected_phase3_mapping_scope_units_2:PASS' ELSE error('FK_expected_phase3_mapping_scope_units_2') END;
SELECT CASE WHEN (SELECT count(*) FROM expected_phase3_scope_source_references)=9 THEN 'EXPECTED_COUNT_expected_phase3_scope_source_references:PASS' ELSE error('EXPECTED_COUNT_expected_phase3_scope_source_references') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_phase3_scope_source_references GROUP BY scope_unit_id,source_reference_id,evidence_role HAVING count(*)>1) THEN 'DUPLICATE_expected_phase3_scope_source_references_0:PASS' ELSE error('DUPLICATE_expected_phase3_scope_source_references_0') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_phase3_scope_source_references e JOIN mapping.phase3_scope_source_references t ON e.scope_unit_id IS NOT DISTINCT FROM t.scope_unit_id AND e.source_reference_id IS NOT DISTINCT FROM t.source_reference_id AND e.evidence_role IS NOT DISTINCT FROM t.evidence_role WHERE NOT (e.scope_unit_id IS NOT DISTINCT FROM t.scope_unit_id AND e.source_reference_id IS NOT DISTINCT FROM t.source_reference_id AND e.evidence_role IS NOT DISTINCT FROM t.evidence_role)) THEN 'CONFLICT_expected_phase3_scope_source_references_0:PASS' ELSE error('CONFLICT_expected_phase3_scope_source_references_0') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_phase3_scope_source_references e WHERE e.scope_unit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM (SELECT * FROM mapping.phase3_mapping_scope_units UNION ALL SELECT * FROM expected_phase3_mapping_scope_units) p WHERE e.scope_unit_id IS NOT DISTINCT FROM p.scope_unit_id)) THEN 'FK_expected_phase3_scope_source_references_0:PASS' ELSE error('FK_expected_phase3_scope_source_references_0') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expected_phase3_scope_source_references e WHERE e.source_reference_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM (SELECT * FROM mapping.phase3_source_references UNION ALL SELECT * FROM expected_phase3_source_references) p WHERE e.source_reference_id IS NOT DISTINCT FROM p.source_reference_id)) THEN 'FK_expected_phase3_scope_source_references_1:PASS' ELSE error('FK_expected_phase3_scope_source_references_1') END;
