SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_mapping_scope_units EXCEPT ALL (SELECT * FROM before_19 UNION ALL SELECT e.* FROM expected_phase3_mapping_scope_units e WHERE NOT EXISTS(SELECT 1 FROM before_19 t WHERE e.scope_unit_id IS NOT DISTINCT FROM t.scope_unit_id))) UNION ALL ((SELECT * FROM before_19 UNION ALL SELECT e.* FROM expected_phase3_mapping_scope_units e WHERE NOT EXISTS(SELECT 1 FROM before_19 t WHERE e.scope_unit_id IS NOT DISTINCT FROM t.scope_unit_id)) EXCEPT ALL SELECT * FROM mapping.phase3_mapping_scope_units)) THEN 'EXACT_DELTA_mapping_phase3_mapping_scope_units:PASS' ELSE error('EXACT_DELTA_mapping_phase3_mapping_scope_units') END;
