SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_representability EXCEPT ALL (SELECT * FROM before_21)) UNION ALL ((SELECT * FROM before_21) EXCEPT ALL SELECT * FROM mapping.phase3_representability)) THEN 'EXACT_DELTA_mapping_phase3_representability:PASS' ELSE error('EXACT_DELTA_mapping_phase3_representability') END;
SELECT CASE WHEN NOT EXISTS((SELECT * FROM mapping.phase3_requirement_capabilities EXCEPT ALL (SELECT * FROM before_22 UNION ALL SELECT e.* FROM expected_phase3_requirement_capabilities e WHERE NOT EXISTS(SELECT 1 FROM before_22 t WHERE e.mapping_id IS NOT DISTINCT FROM t.mapping_id))) UNION ALL ((SELECT * FROM before_22 UNION ALL SELECT e.* FROM expected_phase3_requirement_capabilities e WHERE NOT EXISTS(SELECT 1 FROM before_22 t WHERE e.mapping_id IS NOT DISTINCT FROM t.mapping_id)) EXCEPT ALL SELECT * FROM mapping.phase3_requirement_capabilities)) THEN 'EXACT_DELTA_mapping_phase3_requirement_capabilities:PASS' ELSE error('EXACT_DELTA_mapping_phase3_requirement_capabilities') END;
